"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["89100"],{54751(i){i.exports=JSON.parse('{"id":"F375","slug":"erm-risk-aggregation","name":"Enterprise Risk Aggregation with Correlation","subject":"Risk Management","section":"Risk","topic":"Enterprise risk management","level":"Intermediate","aliases":["ERM","diversification of risk types","capital aggregation","correlation matrix of risks"],"formula":{"latex":"K_{total}=\\\\sqrt{\\\\sum_{i}\\\\sum_{j}\\\\rho_{ij}K_{i}K_{j}}","also":[],"text":"Total capital = square root of the sum over all pairs of (Correlation between risks i and j x Capital for risk i x Capital for risk j)"},"symbols":[{"symbol":"K_i","meaning":"Stand-alone capital for risk type i (market, credit, operational)","unit":"money"},{"symbol":"rho_ij","meaning":"Correlation between risk types i and j (1 on the diagonal)","unit":"number"},{"symbol":"K_total","meaning":"Capital for all risks together","unit":"money"}],"when_to_use":"Use it to combine capital for different risks into one figure. Simply adding them assumes all risks go wrong together. If risks are not perfectly correlated, the total is lower, and the gap is the diversification benefit. The correlations are the most uncertain input and rise in crises.","worked_example":{"problem":"A firm holds stand-alone capital of 100 for market risk, 150 for credit risk and 60 for operational risk. The correlations are 0.5 (market and credit), 0.3 (market and operational) and 0.2 (credit and operational).","inputs":{"k":[100,150,60],"corr":[1,0.5,0.3,0.5,1,0.2,0.3,0.2,1]},"steps":[{"label":"Sum of the stand-alone capital","working":null,"value":"310.0"},{"label":"Total capital = sqrt of the sum of rho x Ki x Kj","working":null,"value":"241.5"},{"label":"Diversification benefit","working":"310-241.454","value":"68.5"},{"label":"As a share of the simple sum","working":"68.5461 / 310","value":"22.1%"}],"answer":"Simply adding the three gives 310.0. Allowing for correlation, the total is 241.5, a diversification benefit of 68.5, or 22.1%."},"calculator":{"available":true,"inputs":[{"id":"k","label":"Capital by risk type","unit":"money","type":"list","default":[100,150,60],"hint":""},{"id":"corr","label":"Correlation matrix, row by row","unit":"","type":"list","default":[1,0.5,0.3,0.5,1,0.2,0.3,0.2,1],"hint":"For three risks enter nine numbers: row 1, then row 2, then row 3."}],"checks":[{"expr":"count(corr)==count(k)*count(k)","message":"The correlation matrix needs one number for each pair, so 9 numbers for 3 risks."}],"steps":[{"id":"simple","label":"Sum of the stand-alone capital","expr":"sum(k)","format":"num1"},{"id":"total","label":"Total capital = sqrt of the sum of rho x Ki x Kj","expr":"sqrt(quadform(k, corr))","format":"num1"},{"id":"benefit","label":"Diversification benefit","expr":"simple-total","format":"num1"},{"id":"pct","label":"As a share of the simple sum","expr":"benefit/simple","format":"pct1"}],"results":["total","benefit"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"simple":310,"total":241.45392935299273,"benefit":68.54607064700727}},"finder":{"finds":"Combined capital after diversification","needs":"Capital per risk, correlation matrix"},"related":[{"slug":"portfolio-variance-two-assets","name":"Risk of a Two-Asset Portfolio"},{"slug":"portfolio-variance-matrix","name":"Portfolio Variance in Matrix Form"},{"slug":"raroc-limit-utilization","name":"RAROC and Risk Limit Utilization"}],"related_ids":["F230","F396","F376"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>K</mi><mrow><mi>t</mi><mi>o</mi><mi>t</mi><mi>a</mi><mi>l</mi></mrow></msub><mo>=</mo><msqrt><mrow><munder><mo>\u2211</mo><mi>i</mi></munder><munder><mo>\u2211</mo><mi>j</mi></munder><msub><mi>\u03C1</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><msub><mi>K</mi><mi>i</mi></msub><msub><mi>K</mi><mi>j</mi></msub></mrow></msqrt></mrow><annotation encoding=\\"application/x-tex\\">K_{total}=\\\\sqrt{\\\\sum_{i}\\\\sum_{j}\\\\rho_{ij}K_{i}K_{j}}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msub><mi>K</mi><mrow><mi>t</mi><mi>o</mi><mi>t</mi><mi>a</mi><mi>l</mi></mrow></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle K_{total}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><msqrt><mrow><munder><mo>\u2211</mo><mi>i</mi></munder><munder><mo>\u2211</mo><mi>j</mi></munder><msub><mi>\u03C1</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><msub><mi>K</mi><mi>i</mi></msub><msub><mi>K</mi><mi>j</mi></msub></mrow></msqrt></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\sqrt{\\\\sum_{i}\\\\sum_{j}\\\\rho_{ij}K_{i}K_{j}}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"endowment-spending-rule","name":"Endowment Spending Rule (Yale)"},"next":{"slug":"ev-to-equity-value","name":"Enterprise Value to Equity Value"},"lesson":null,"total":522}')}}]);